#include <bits/stdc++.h>
using namespace std;

#include "atcoder/modint.hpp"
using mint = atcoder::modint998244353;

vector<pair<char, int>> RunLengthEncoding(string& S) {
  if (S.empty()) return {};
  vector<pair<char, int>> ret;
  char c = S[0];
  int n = 1;
  for (int i = 1; i < (int)S.size(); i++) {
    if (S[i] == c)
      n++;
    else {
      ret.emplace_back(c, n);
      c = S[i], n = 1;
    }
  }
  ret.emplace_back(c, n);
  return ret;
}

int main() {
  int N;
  string S;
  cin >> N >> S;
  for (int i = 0; i + 1 < N; i++) {
    if (S[i] >= '2' and S[i + 1] >= '2') {
      cout << "-1\n";
      exit(0);
    }
  }
  auto rle = RunLengthEncoding(S);
  mint t = 0;
  char last = '1';
  while (!rle.empty()) {
    char c;
    mint n;
    tie(c, n) = rle.back();
    rle.pop_back();
    if (c == '1') {
      n += t * (last - '1');
      t += n;
    } else {
      t += 1;
    }
    last = c;
  }
  cout << (t - 1).val() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
#include "atcoder/modint.hpp"
using mint = atcoder::modint998244353;

int main() {
  int N;
  string S;
  cin >> N >> S;
  for(int i=0; i+1<N; i++){
    if(S[i]!='1' && S[i+1]!='1'){
      cout << "-1";
      return 0;
    }
  }
  mint ans=0;
  for(int i=N-1; i>=1; i--){
    ans++; //S[i]を消すのに1手かかる
    ans += ans*(S[i]-'1'); //S[i]によって増える'1'の個数をansに加算
  }
  cout << ans.val();
  return 0;
}
